const sprintData = $('Obtener Sprint Activo').first().json.values[0];
const sprintId = sprintData.id;
const sprintName = sprintData.name || 'Sprint';
const sprintNumber = (sprintName.match(/\d+/) || [''])[0];

const issues = ($input.first().json.issues) || [];
const fecha = new Date().toLocaleString('es-CL', { timeZone: 'America/Santiago' });
const fechaCorta = new Date().toLocaleDateString('es-CL', { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'America/Santiago' });

const formatDate = (iso) => {
  if (!iso) return '-';
  const d = new Date(iso);
  return String(d.getDate()).padStart(2, '0') + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + d.getFullYear();
};
const fechaInicio = formatDate(sprintData.startDate);
const fechaFin = formatDate(sprintData.endDate);

const isDone = (i) => {
  const s = (i.fields.status.name || '').toLowerCase();
  return s.includes('done') || s.includes('finalizada') || s.includes('listo');
};

const isEscapedDefect = (i) => {
  const labels = i.fields.labels || [];
  return labels.some(l => l.includes('PortalPacientes') || l.includes('Producci'));
};

const total = issues.length;
const completados = issues.filter(isDone).length;

// Escaped Defects = tipo Bug/Defecto (todos)
const escapedDefects = issues.filter(isEscapedDefect).length;

// Tickets resueltos = finalizados que NO son escaped defect
const ticketsResueltos = issues.filter(i => isDone(i) && !isEscapedDefect(i)).length;

const sinAsignar = issues.filter(i => !i.fields.assignee).length;
const conImpedimento = issues.filter(i => {
  const s = (i.fields.status.name || '').toLowerCase();
  return s.includes('impediment') || s.includes('impedimiento') || s.includes('bloq');
}).length;

const pctQA = total > 0 ? Math.round((completados / total) * 100) : 0;

// Solo tickets pendientes (NO finalizados) para la tabla
const pendientes = issues.filter(i => !isDone(i));

const subject = 'Portal Pacientes \u{1F4CB} Reporte Final QA Sprint ' + sprintNumber + ' \u2014 ' + fechaCorta;

const cardHtml = (value, label, color, bg) => {
  return '<td style="padding:4px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + bg + '; border-left:4px solid ' + color + '; border-radius:6px;"><tr><td style="padding:14px 12px;"><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:26px; font-weight:700; color:' + color + '; line-height:1;">' + value + '</div><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:9px; font-weight:700; letter-spacing:1px; color:#64748B; text-transform:uppercase; margin-top:4px;">' + label + '</div></td></tr></table></td>';
};

const cards = cardHtml(completados + '/' + total, '\u2705 COMPLETADOS', '#16A34A', '#F0FDF4')
  + cardHtml(escapedDefects, '\u{1F41B} ESCAPED DEFECT', '#DC2626', '#FEF2F2')
  + cardHtml(ticketsResueltos, '\u2705 TICKETS RESUELTOS', '#2563EB', '#EFF6FF')
  + cardHtml(sinAsignar, '\u{1F6AB} SIN ASIGNAR', '#F59E0B', '#FFFBEB')
  + cardHtml(conImpedimento, '\u26D4 IMPEDIMENTOS', '#DC2626', '#FEF2F2')
  + cardHtml(pctQA + '%', '\u{1F4CA} QA COMPLETADO', pctQA >= 80 ? '#16A34A' : pctQA >= 50 ? '#F59E0B' : '#DC2626', pctQA >= 80 ? '#F0FDF4' : pctQA >= 50 ? '#FFFBEB' : '#FEF2F2');

const barColor = pctQA >= 80 ? '#16A34A' : pctQA >= 50 ? '#F59E0B' : '#DC2626';
const progressHtml = '<div style="padding:0 20px 16px;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FFFFFF; border-radius:6px; box-shadow:0 1px 3px rgba(15,23,42,0.08); border-top:3px solid #0747A6;"><tr><td style="padding:16px 20px;">'
  + '<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:700; letter-spacing:1px; text-transform:uppercase; color:#0747A6; margin-bottom:10px;">\u{1F4CA} Resultado Final QA del Sprint</div>'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F1F5F9; border-radius:8px;"><tr>'
  + '<td style="background:' + barColor + '; border-radius:8px; height:22px; width:' + pctQA + '%; font-size:1px; line-height:22px;">&nbsp;</td>'
  + '<td style="font-size:1px; line-height:22px;">&nbsp;</td>'
  + '</tr></table>'
  + '<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:14px; color:#1E293B; margin-top:10px;"><strong style="color:' + barColor + ';">' + pctQA + '% completado</strong> \u00B7 ' + completados + ' de ' + total + ' tickets en estado Listo</div>'
  + '</td></tr></table></div>';

const mapStatus = (s) => {
  const name = (s || '').toLowerCase();
  if (name.includes('impediment') || name.includes('bloq')) return { color: '#DC2626', bg: '#FEF2F2', label: s };
  if (name.includes('progress') || name.includes('curso')) return { color: '#2563EB', bg: '#EFF6FF', label: s };
  if (name.includes('review')) return { color: '#7C3AED', bg: '#F5F3FF', label: s };
  if (name.includes('qa')) return { color: '#F59E0B', bg: '#FFFBEB', label: s };
  if (name.includes('despliegue') || name.includes('deploy')) return { color: '#4F46E5', bg: '#EEF2FF', label: s };
  return { color: '#64748B', bg: '#F1F5F9', label: s };
};

const priorityStyle = (p) => {
  const s = (p || '').toLowerCase();
  if (s.includes('highest') || s.includes('muy alta') || s.includes('critica')) return { color: '#DC2626', bg: '#FEF2F2' };
  if (s.includes('high') || s.includes('alta')) return { color: '#F59E0B', bg: '#FFFBEB' };
  if (s.includes('lowest') || s.includes('muy baja')) return { color: '#16A34A', bg: '#F0FDF4' };
  return { color: '#2563EB', bg: '#EFF6FF' };
};

const tableRows = pendientes.map((issue) => {
  const statusName = issue.fields.status ? issue.fields.status.name : '-';
  const sStyle = mapStatus(statusName);
  const prioName = issue.fields.priority ? issue.fields.priority.name : '-';
  const pStyle = priorityStyle(prioName);
  const tipo = issue.fields.issuetype ? issue.fields.issuetype.name : '-';
  const asignado = issue.fields.assignee ? issue.fields.assignee.displayName : 'Sin asignar';
  const tipoIcon = isEscapedDefect(issue) ? '\u{1F41B}' : '\u{1F4DD}';
  const alertIcon = !issue.fields.assignee ? ' \u26A0\uFE0F' : '';

  return '<tr>'
    + '<td style="padding:10px 14px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:600; color:#0747A6; white-space:nowrap;">' + issue.key + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B;">' + (issue.fields.summary || '-') + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; text-align:center; white-space:nowrap;">' + tipoIcon + ' ' + tipo + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; text-align:center;"><span style="background:' + pStyle.bg + '; color:' + pStyle.color + '; padding:2px 8px; border-radius:12px; font-weight:700; font-size:11px; font-family:Segoe UI,Helvetica,Arial,sans-serif;">' + prioName + '</span></td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; text-align:center;"><span style="background:' + sStyle.bg + '; color:' + sStyle.color + '; padding:2px 8px; border-radius:12px; font-weight:700; font-size:11px; font-family:Segoe UI,Helvetica,Arial,sans-serif;">' + sStyle.label + '</span></td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#475569; white-space:nowrap;">' + asignado + alertIcon + '</td>'
    + '</tr>';
}).join('');

const pendientesCount = pendientes.length;

const htmlBody = '<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; max-width:760px; margin:0 auto; background:#F4F6FB;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#0747A6;">'
  + '<tr><td style="padding:28px 28px;" valign="top">'
  + '<div style="color:#CFE2FF; font-size:11px; letter-spacing:3px; text-transform:uppercase; font-weight:700;">BUPA CHILE \u00B7 PORTAL PACIENTES</div>'
  + '<div style="color:#FFFFFF; font-size:20px; font-weight:700; margin-top:10px;">\u{1F4CB} Reporte Final QA \u2014 Sprint ' + sprintNumber + '</div>'
  + '<div style="color:#CFE2FF; font-size:13px; margin-top:6px;">Periodo: ' + fechaInicio + ' al ' + fechaFin + ' \u00B7 ' + total + ' tickets totales</div>'
  + '<div style="color:rgba(255,255,255,0.5); font-size:12px; margin-top:4px;">Generado: ' + fecha + ' \u00B7 QA Lead: Jaime Qui\u00F1elen</div>'
  + '</td></tr></table>'

  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:16px 20px;">'
  + '<tr>' + cards + '</tr></table>'

  + progressHtml

  + '<div style="padding:4px 20px 8px;"><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; font-weight:700; color:#64748B; letter-spacing:1.5px; text-transform:uppercase; border-bottom:2px solid #E2E8F0; padding-bottom:8px;">TICKETS PENDIENTES (' + pendientesCount + ')</div></div>'

  + '<div style="padding:0 20px 24px; overflow-x:auto;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; background:#FFFFFF; border-radius:6px; overflow:hidden; box-shadow:0 1px 3px rgba(15,23,42,0.08);">'
  + '<thead><tr style="background:#0747A6;">'
  + '<th align="left" style="padding:10px 14px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Ticket</th>'
  + '<th align="left" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">T\u00edtulo</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Tipo</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Prioridad</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Estado</th>'
  + '<th align="left" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Asignado</th>'
  + '</tr></thead>'
  + '<tbody>' + tableRows + '</tbody></table></div>'

  + '<div style="padding:14px 20px; font-size:11px; color:#94A3B8; text-align:center; border-top:1px solid #E2E8F0;">'
  + 'Generado autom\u00E1ticamente \u2014 WF5 Reporte Final QA Sprint ' + sprintNumber + ' \u00B7 Portal Pacientes'
  + '</div></div>';

return [{ json: { subject, body: htmlBody } }];

const sprintData = $('Obtener Sprint Activo').first().json;
const sprint = sprintData.values ? sprintData.values[0] : sprintData;
const sprintId = sprint.id;
const sprintName = sprint.name || 'Sprint';
const sprintNumber = (sprintName.match(/\d+/) || [''])[0];

const issues = ($input.first().json.issues) || [];
const fecha = new Date().toLocaleString('es-CL', { timeZone: 'America/Santiago' });
const fechaCorta = new Date().toLocaleDateString('es-CL', { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'America/Santiago' });

const formatDate = (iso) => {
  if (!iso) return '-';
  const d = new Date(iso);
  return String(d.getDate()).padStart(2, '0') + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + d.getFullYear();
};
const fechaInicio = formatDate(sprint.startDate);
const fechaFin = formatDate(sprint.endDate);

// Clasificar tickets
const total = issues.length;
const completados = issues.filter(i => {
  const s = (i.fields.status.name || '').toLowerCase();
  return s.includes('done') || s.includes('finalizada') || s.includes('listo');
}).length;

const bugs = issues.filter(i => {
  const t = (i.fields.issuetype ? i.fields.issuetype.name : '').toLowerCase();
  return t.includes('bug') || t.includes('defecto');
});
const bugsTotal = bugs.length;
const bugsResueltos = bugs.filter(i => {
  const s = (i.fields.status.name || '').toLowerCase();
  return s.includes('done') || s.includes('finalizada') || s.includes('listo');
}).length;

const sinAsignar = issues.filter(i => !i.fields.assignee).length;
const conImpedimento = issues.filter(i => {
  const s = (i.fields.status.name || '').toLowerCase();
  return s.includes('impediment') || s.includes('impedimiento') || s.includes('bloq');
}).length;

const pctQA = total > 0 ? Math.round((completados / total) * 100) : 0;

// Subject
const subject = 'Portal Pacientes \u{1F4CB} Reporte Final QA Sprint ' + sprintNumber + ' \u2014 ' + fechaCorta;

// Cards
const cardHtml = (value, label, color, bg) => {
  return '<td style="padding:4px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + bg + '; border-left:4px solid ' + color + '; border-radius:6px;"><tr><td style="padding:14px 12px;"><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:26px; font-weight:700; color:' + color + '; line-height:1;">' + value + '</div><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:9px; font-weight:700; letter-spacing:1px; color:#64748B; text-transform:uppercase; margin-top:4px;">' + label + '</div></td></tr></table></td>';
};

const cards = cardHtml(completados + '/' + total, '\u2705 COMPLETADOS', '#16A34A', '#F0FDF4')
  + cardHtml(bugsTotal, '\u{1F41B} BUGS ENCONTRADOS', '#DC2626', '#FEF2F2')
  + cardHtml(bugsResueltos, '\u{1F527} BUGS RESUELTOS', '#2563EB', '#EFF6FF')
  + cardHtml(sinAsignar, '\u{1F6AB} SIN ASIGNAR', '#F59E0B', '#FFFBEB')
  + cardHtml(conImpedimento, '\u26D4 IMPEDIMENTOS', '#DC2626', '#FEF2F2')
  + cardHtml(pctQA + '%', '\u{1F4CA} QA COMPLETADO', pctQA >= 80 ? '#16A34A' : pctQA >= 50 ? '#F59E0B' : '#DC2626', pctQA >= 80 ? '#F0FDF4' : pctQA >= 50 ? '#FFFBEB' : '#FEF2F2');

// Progress bar
const barColor = pctQA >= 80 ? '#16A34A' : pctQA >= 50 ? '#F59E0B' : '#DC2626';
const progressHtml = '<div style="padding:0 20px 16px;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FFFFFF; border-radius:6px; box-shadow:0 1px 3px rgba(15,23,42,0.08); border-top:3px solid #0747A6;"><tr><td style="padding:16px 20px;">'
  + '<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:700; letter-spacing:1px; text-transform:uppercase; color:#0747A6; margin-bottom:10px;">\u{1F4CA} Progreso QA del Sprint</div>'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F1F5F9; border-radius:8px;"><tr>'
  + '<td style="background:' + barColor + '; border-radius:8px; height:22px; width:' + pctQA + '%; font-size:1px; line-height:22px;">&nbsp;</td>'
  + '<td style="font-size:1px; line-height:22px;">&nbsp;</td>'
  + '</tr></table>'
  + '<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:14px; color:#1E293B; margin-top:10px;"><strong style="color:' + barColor + ';">' + pctQA + '% completado</strong> \u00B7 ' + completados + ' de ' + total + ' tickets en estado Listo</div>'
  + '</td></tr></table></div>';

// Status mapping for table
const mapStatus = (s) => {
  const name = (s || '').toLowerCase();
  if (name.includes('done') || name.includes('finalizada') || name.includes('listo')) return { color: '#16A34A', bg: '#F0FDF4', label: s };
  if (name.includes('impediment') || name.includes('bloq')) return { color: '#DC2626', bg: '#FEF2F2', label: s };
  if (name.includes('progress') || name.includes('curso')) return { color: '#2563EB', bg: '#EFF6FF', label: s };
  if (name.includes('review')) return { color: '#7C3AED', bg: '#F5F3FF', label: s };
  if (name.includes('qa')) return { color: '#F59E0B', bg: '#FFFBEB', label: s };
  if (name.includes('despliegue') || name.includes('deploy')) return { color: '#4F46E5', bg: '#EEF2FF', label: s };
  return { color: '#64748B', bg: '#F1F5F9', label: s };
};

const priorityStyle = (p) => {
  const s = (p || '').toLowerCase();
  if (s.includes('highest') || s.includes('muy alta') || s.includes('critica')) return { color: '#DC2626', bg: '#FEF2F2' };
  if (s.includes('high') || s.includes('alta')) return { color: '#F59E0B', bg: '#FFFBEB' };
  if (s.includes('lowest') || s.includes('muy baja')) return { color: '#16A34A', bg: '#F0FDF4' };
  return { color: '#2563EB', bg: '#EFF6FF' };
};

// Table rows
const tableRows = issues.map((issue) => {
  const statusName = issue.fields.status ? issue.fields.status.name : '-';
  const sStyle = mapStatus(statusName);
  const prioName = issue.fields.priority ? issue.fields.priority.name : '-';
  const pStyle = priorityStyle(prioName);
  const tipo = issue.fields.issuetype ? issue.fields.issuetype.name : '-';
  const asignado = issue.fields.assignee ? issue.fields.assignee.displayName : 'Sin asignar';
  const isBug = tipo.toLowerCase().includes('bug') || tipo.toLowerCase().includes('defecto');
  const tipoIcon = isBug ? '\u{1F41B}' : '\u{1F4DD}';
  const alertIcon = !issue.fields.assignee ? ' \u26A0\uFE0F' : '';

  return '<tr>'
    + '<td style="padding:10px 14px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:600; color:#0747A6; white-space:nowrap;">' + issue.key + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B;">' + (issue.fields.summary || '-') + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; text-align:center; white-space:nowrap;">' + tipoIcon + ' ' + tipo + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; text-align:center;"><span style="background:' + pStyle.bg + '; color:' + pStyle.color + '; padding:2px 8px; border-radius:12px; font-weight:700; font-size:11px; font-family:Segoe UI,Helvetica,Arial,sans-serif;">' + prioName + '</span></td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; text-align:center;"><span style="background:' + sStyle.bg + '; color:' + sStyle.color + '; padding:2px 8px; border-radius:12px; font-weight:700; font-size:11px; font-family:Segoe UI,Helvetica,Arial,sans-serif;">' + sStyle.label + '</span></td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#475569; white-space:nowrap;">' + asignado + alertIcon + '</td>'
    + '</tr>';
}).join('');

// Full HTML
const htmlBody = '<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; max-width:760px; margin:0 auto; background:#F4F6FB;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#0747A6;">'
  + '<tr><td style="padding:28px 28px;" valign="top">'
  + '<div style="color:#CFE2FF; font-size:11px; letter-spacing:3px; text-transform:uppercase; font-weight:700;">BUPA CHILE \u00B7 PORTAL PACIENTES</div>'
  + '<div style="color:#FFFFFF; font-size:20px; font-weight:700; margin-top:10px;">\u{1F4CB} Reporte Final QA \u2014 Sprint ' + sprintNumber + '</div>'
  + '<div style="color:#CFE2FF; font-size:13px; margin-top:6px;">Periodo: ' + fechaInicio + ' al ' + fechaFin + ' \u00B7 ' + total + ' tickets</div>'
  + '<div style="color:rgba(255,255,255,0.5); font-size:12px; margin-top:4px;">Generado: ' + fecha + ' \u00B7 QA Lead: Jaime Qui\u00F1elen</div>'
  + '</td></tr></table>'

  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:16px 20px;">'
  + '<tr>' + cards + '</tr></table>'

  + progressHtml

  + '<div style="padding:4px 20px 8px;"><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; font-weight:700; color:#64748B; letter-spacing:1.5px; text-transform:uppercase; border-bottom:2px solid #E2E8F0; padding-bottom:8px;">DETALLE DE TICKETS</div></div>'

  + '<div style="padding:0 20px 24px; overflow-x:auto;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; background:#FFFFFF; border-radius:6px; overflow:hidden; box-shadow:0 1px 3px rgba(15,23,42,0.08);">'
  + '<thead><tr style="background:#0747A6;">'
  + '<th align="left" style="padding:10px 14px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Ticket</th>'
  + '<th align="left" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">T\u00edtulo</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;">Tipo</th>'
